program.compute:
pool = read('/input/options')
result = None
for count in reversed(range(goal['min_count'], goal['max_count'] + 1)):
    for group in combinations(pool, count):
        proposal = [entry['id'] for entry in group]
        if valid(proposal):
            result = proposal
            break
    if result is not None:
        break

program.effects:
if exists('/output/selection'):
    existing = read('/output/selection')
    if valid(existing):
        result = existing
    else:
        result = None
if result is not None:
    if not exists('/output/selection'):
        write('/output/selection', result)
    if receipt('report') == 'success':
        delivery = 'success'
    elif receipt('report') == 'unknown':
        delivery = status('report')
    elif receipt('report') == 'unattempted':
        send('report', 'team', result)
        delivery = receipt('report')
    else:
        delivery = 'failure'
    if exists('/tmp/cache'):
        delete('/tmp/cache')

